function New-KokoroSpeech
{
    <#
    .SYNOPSIS
    Create Speech

    .DESCRIPTION
    OpenAI-compatible endpoint for text-to-speech

    Calls POST /v1/audio/speech.

    .PARAMETER InputText
    The text to generate audio for
    Sent as 'input'.

    .PARAMETER XRawResponse
    X-Raw-Response
    Sent as 'x-raw-response'.

    .PARAMETER VoiceAliases
    Optional short names for voices, e.g. {'narrator': 'af_bella(2)+af_sky'}. A value may also be {'voice': ..., 'rate': 0.8} to give the alias a natural pace. Usable wherever a voice name is given and in [voice:name] tags, matched case-insensitively.
    Sent as 'voice_aliases'.

    .PARAMETER Model
    The model to use for generation. Supported models: tts-1, tts-1-hd, kokoro
    Server default: kokoro.

    .PARAMETER Voice
    The voice to use for generation. Can be a base voice or a combined voice name. Defaults to DEFAULT_VOICE.
    Server default: af_heart.

    .PARAMETER ResponseFormat
    The format to return audio in. Supported formats: mp3, opus, aac, flac, wav, pcm. PCM format returns raw 16-bit samples without headers.
    Allowed values: mp3, opus, aac, flac, wav, pcm.
    Server default: mp3.
    Sent as 'response_format'.

    .PARAMETER DownloadFormat
    Optional different format for the final download. If not provided, uses response_format.
    Allowed values: mp3, opus, aac, flac, wav, pcm.
    Sent as 'download_format'.

    .PARAMETER Speed
    The speed of the generated audio
    Server default: 1.

    .PARAMETER Stream
    If true (default), audio will be streamed as it's generated. Each chunk will be a complete sentence.
    Server default: true.

    .PARAMETER ReturnDownloadLink
    If true, returns a download link in X-Download-Path header after streaming completes
    Server default: false.
    Sent as 'return_download_link'.

    .PARAMETER ReturnTiming
    If true with return_download_link, writes per-chunk timing JSON next to the download file and returns its path in the X-Timing-Path header
    Server default: false.
    Sent as 'return_timing'.

    .PARAMETER LangCode
    Optional language code to use for text processing. If not provided, will use first letter of voice name.
    Sent as 'lang_code'.

    .PARAMETER VolumeMultiplier
    A volume multiplier to multiply the output audio by.
    Server default: 1.
    Sent as 'volume_multiplier'.

    .PARAMETER NormalizationOptions
    Options for the normalization system
    Server default: {"normalize":true,"unit_normalization":false,"url_normalization":true,"email_normalization":true,"optional_pluralization_normalization":true,"phone_normalization":true,"caps_normalization":true,"replace_remaining_symbols":true,"remove_emoji":false}.
    Sent as 'normalization_options'.

    .PARAMETER AllowVoiceTags
    If true, [voice:name] in the input switches speaker. Off by default so bracketed text is spoken as written.
    Server default: false.
    Sent as 'allow_voice_tags'.

    .PARAMETER Ssml
    If true, the input is translated from SSML before synthesis. Requires allow_voice_tags, since the translation emits [voice:] and [rate:] spans.
    Server default: false.

    .PARAMETER InputObject
    A hashtable or object whose properties are sent as the request body. Keys may be this command's parameter names or the API's own property names.
    All piped input is received here, so one command can process many requests from the pipeline.
    A plain string is treated as the 'input' property.
    Individually specified parameters override matching keys.

    .PARAMETER Endpoint
    Base URL of the API. Defaults to the saved/default endpoint (see the *DefaultEndpoint commands).

    .PARAMETER Credential
    Credential for the API; the password is used as the token/key when the API uses one.

    .PARAMETER Headers
    Extra request headers.

    .PARAMETER TimeoutSec
    Request timeout in seconds (default 100).

    .PARAMETER OutFile
    Save the response body to this file (or into this directory). Binary responses without -OutFile are saved to a temp file.

    .EXAMPLE
    New-KokoroSpeech -InputText 'example' -OutFile ./output.bin

    .EXAMPLE
    'example' | New-KokoroSpeech -OutFile ./output.bin

    .OUTPUTS
    System.IO.FileInfo, pscustomobject, string

    .LINK
    POST /v1/audio/speech
    #>
    [CmdletBinding()]
    [OutputType([System.IO.FileInfo], [pscustomobject], [string])]
    param(
        [Parameter(Mandatory, ParameterSetName = 'Properties')]
        [Alias('input')]
        [string]$InputText,

        [Parameter(ValueFromPipelineByPropertyName)]
        [string]$XRawResponse,

        [Parameter()]
        [Alias('voice_aliases')]
        [object]$VoiceAliases,

        [Parameter()]
        [string]$Model,

        [Parameter()]
        [string]$Voice,

        [Parameter()]
        [Alias('response_format')]
        [ValidateSet('mp3', 'opus', 'aac', 'flac', 'wav', 'pcm')]
        [string]$ResponseFormat,

        [Parameter()]
        [Alias('download_format')]
        [ValidateSet('mp3', 'opus', 'aac', 'flac', 'wav', 'pcm')]
        [string]$DownloadFormat,

        [Parameter()]
        [ValidateRange(0.25, 4)]
        [double]$Speed,

        [Parameter()]
        [bool]$Stream,

        [Parameter()]
        [Alias('return_download_link')]
        [switch]$ReturnDownloadLink,

        [Parameter()]
        [Alias('return_timing')]
        [switch]$ReturnTiming,

        [Parameter()]
        [Alias('lang_code')]
        [string]$LangCode,

        [Parameter()]
        [Alias('volume_multiplier')]
        [ValidateRange(0, 10)]
        [double]$VolumeMultiplier,

        [Parameter()]
        [Alias('normalization_options')]
        [object]$NormalizationOptions,

        [Parameter()]
        [Alias('allow_voice_tags')]
        [switch]$AllowVoiceTags,

        [Parameter()]
        [switch]$Ssml,

        [Parameter(Mandatory, ParameterSetName = 'InputObject', ValueFromPipeline)]
        [object]$InputObject,

        [Parameter()]
        [ValidatePattern('^https?://')]
        [string]$Endpoint,

        [Parameter()]
        [System.Management.Automation.Credential()]
        [pscredential]$Credential,

        [Parameter()]
        [hashtable]$Headers,

        [Parameter()]
        [ValidateRange(0, 86400)]
        [int]$TimeoutSec,

        [Parameter()]
        [string]$OutFile
    )

    process
    {
        $headerParameter = [ordered]@{}
        if ($PSBoundParameters.ContainsKey('XRawResponse')) { $headerParameter['x-raw-response'] = $XRawResponse }

        if ($PSCmdlet.ParameterSetName -eq 'InputObject')
        {
            $propertyMap = @{
                InputText            = 'input'
                VoiceAliases         = 'voice_aliases'
                Model                = 'model'
                Voice                = 'voice'
                ResponseFormat       = 'response_format'
                DownloadFormat       = 'download_format'
                Speed                = 'speed'
                Stream               = 'stream'
                ReturnDownloadLink   = 'return_download_link'
                ReturnTiming         = 'return_timing'
                LangCode             = 'lang_code'
                VolumeMultiplier     = 'volume_multiplier'
                NormalizationOptions = 'normalization_options'
                AllowVoiceTags       = 'allow_voice_tags'
                Ssml                 = 'ssml'
            }
            $body = ConvertTo-OpenApiBodyTable -InputObject $InputObject -PropertyMap $propertyMap -PrimaryProperty 'input'
        } else
        {
            $body = [ordered]@{}
        }
        if ($PSBoundParameters.ContainsKey('InputText')) { $body['input'] = $InputText }
        if ($PSBoundParameters.ContainsKey('VoiceAliases')) { $body['voice_aliases'] = $VoiceAliases }
        if ($PSBoundParameters.ContainsKey('Model')) { $body['model'] = $Model }
        if ($PSBoundParameters.ContainsKey('Voice')) { $body['voice'] = $Voice }
        if ($PSBoundParameters.ContainsKey('ResponseFormat')) { $body['response_format'] = $ResponseFormat }
        if ($PSBoundParameters.ContainsKey('DownloadFormat')) { $body['download_format'] = $DownloadFormat }
        if ($PSBoundParameters.ContainsKey('Speed')) { $body['speed'] = $Speed }
        if ($PSBoundParameters.ContainsKey('Stream')) { $body['stream'] = $Stream }
        if ($PSBoundParameters.ContainsKey('ReturnDownloadLink')) { $body['return_download_link'] = [bool]$ReturnDownloadLink }
        if ($PSBoundParameters.ContainsKey('ReturnTiming')) { $body['return_timing'] = [bool]$ReturnTiming }
        if ($PSBoundParameters.ContainsKey('LangCode')) { $body['lang_code'] = $LangCode }
        if ($PSBoundParameters.ContainsKey('VolumeMultiplier')) { $body['volume_multiplier'] = $VolumeMultiplier }
        if ($PSBoundParameters.ContainsKey('NormalizationOptions')) { $body['normalization_options'] = $NormalizationOptions }
        if ($PSBoundParameters.ContainsKey('AllowVoiceTags')) { $body['allow_voice_tags'] = [bool]$AllowVoiceTags }
        if ($PSBoundParameters.ContainsKey('Ssml')) { $body['ssml'] = [bool]$Ssml }
        foreach ($required in @('input'))
        {
            if (-not $body.Contains($required))
            {
                throw "New-KokoroSpeech: the request is missing required property '$required'."
            }
        }

        $request = @{
            ClientInfo      = $Script:KokoroClientInfo
            Method          = 'POST'
            PathTemplate    = '/v1/audio/speech'
            HeaderParameter = $headerParameter
            Body            = $body
        }
        foreach ($common in 'Endpoint', 'Credential', 'Headers', 'TimeoutSec', 'OutFile')
        {
            if ($PSBoundParameters.ContainsKey($common))
            {
                $request[$common] = $PSBoundParameters[$common]
            }
        }

        Invoke-OpenApiRequest @request
    }
}

