function Optimize-KokoroSpeech
{
    <#
    .SYNOPSIS
    Tune Speech

    .DESCRIPTION
    Tune a voice from the reference clip, then speak `request` with it.

    return_voice_pack=true returns the [510, 1, 256] .pt instead. save_voice=<name>
    keeps it as VOICES_DIR/<name>_tuned.pt and needs ALLOW_LOCAL_VOICE_SAVING.
    Otherwise the pack lives in the temp dir for the length of the response only.

    Calls POST /dev/tune.

    .PARAMETER Audio
    Reference clip, 3 to 30 s, one speaker

    .PARAMETER Request
    JSON body as for /v1/audio/speech, minus voice

    .PARAMETER ProsodyHead
    Prosody Head
    Server default: true.
    Sent as 'prosody_head'.

    .PARAMETER Fmax
    Fmax

    .PARAMETER ReturnVoicePack
    Return Voice Pack
    Server default: false.
    Sent as 'return_voice_pack'.

    .PARAMETER SaveVoice
    Save Voice
    Sent as 'save_voice'.

    .PARAMETER Endpoint
    Base URL of the API. Defaults to the saved/default endpoint (see the *DefaultEndpoint commands).

    .PARAMETER Credential
    Credential for the API; the password is used as the token/key when the API uses one.

    .PARAMETER Headers
    Extra request headers.

    .PARAMETER TimeoutSec
    Request timeout in seconds (default 100).

    .PARAMETER OutFile
    Save the response body to this file (or into this directory). Binary responses without -OutFile are saved to a temp file.

    .EXAMPLE
    Optimize-KokoroSpeech -Audio './file' -OutFile ./output.bin

    .OUTPUTS
    System.IO.FileInfo, pscustomobject, string

    .LINK
    POST /dev/tune
    #>
    [CmdletBinding()]
    [OutputType([System.IO.FileInfo], [pscustomobject], [string])]
    param(
        [Parameter(Mandatory, ValueFromPipelineByPropertyName)]
        [Alias('FullName', 'Path')]
        [ValidateScript({ Test-Path -LiteralPath $_ -PathType Leaf })]
        [string]$Audio,

        [Parameter(ValueFromPipelineByPropertyName)]
        [string]$Request,

        [Parameter(ValueFromPipelineByPropertyName)]
        [Alias('prosody_head')]
        [bool]$ProsodyHead,

        [Parameter(ValueFromPipelineByPropertyName)]
        [ValidateRange(60, 1000)]
        [double]$Fmax,

        [Parameter(ValueFromPipelineByPropertyName)]
        [Alias('return_voice_pack')]
        [switch]$ReturnVoicePack,

        [Parameter(ValueFromPipelineByPropertyName)]
        [Alias('save_voice')]
        [string]$SaveVoice,

        [Parameter()]
        [ValidatePattern('^https?://')]
        [string]$Endpoint,

        [Parameter()]
        [System.Management.Automation.Credential()]
        [pscredential]$Credential,

        [Parameter()]
        [hashtable]$Headers,

        [Parameter()]
        [ValidateRange(0, 86400)]
        [int]$TimeoutSec,

        [Parameter()]
        [string]$OutFile
    )

    process
    {
        $body = [ordered]@{}
        $body['audio'] = (Get-Item -LiteralPath $Audio)
        if ($PSBoundParameters.ContainsKey('Request')) { $body['request'] = $Request }
        if ($PSBoundParameters.ContainsKey('ProsodyHead')) { $body['prosody_head'] = $ProsodyHead }
        if ($PSBoundParameters.ContainsKey('Fmax')) { $body['fmax'] = $Fmax }
        if ($PSBoundParameters.ContainsKey('ReturnVoicePack')) { $body['return_voice_pack'] = [bool]$ReturnVoicePack }
        if ($PSBoundParameters.ContainsKey('SaveVoice')) { $body['save_voice'] = $SaveVoice }

        $request = @{
            ClientInfo   = $Script:KokoroClientInfo
            Method       = 'POST'
            PathTemplate = '/dev/tune'
            Body         = $body
            BodyType     = 'multipart'
        }
        foreach ($common in 'Endpoint', 'Credential', 'Headers', 'TimeoutSec', 'OutFile')
        {
            if ($PSBoundParameters.ContainsKey($common))
            {
                $request[$common] = $PSBoundParameters[$common]
            }
        }

        Invoke-OpenApiRequest @request
    }
}

